import datetime
import math
import re
import polars as pl


def transform(raw: pl.DataFrame) -> pl.DataFrame:
    def clean_str(col: str) -> pl.Expr:
        s = pl.col(col).str.strip_chars()
        return pl.when(s.is_in(["", "N/A", "n/a", "-", "null", "NULL"])).then(None).otherwise(s)

    # Phone e164 normalization for New Zealand (country code 64)
    def clean_phone(col: str) -> pl.Expr:
        c = clean_str(col)
        digits = c.str.replace_all(r"\D", "")
        return pl.when(digits.is_not_null()).then(
            pl.concat_str([pl.lit("+"), digits])
        ).otherwise(None)

    # European number format: 10.159,77 -> 10159.77
    def clean_number(col: str) -> pl.Expr:
        c = clean_str(col)
        cleaned = c.str.replace_all(r"\.", "").str.replace_all(r",", ".")
        return cleaned.cast(pl.Float64, strict=False).round(2)

    return raw.select(
        contact_id=clean_str("ID").str.to_uppercase(),
        full_name=clean_str("Contact Name"),
        email=clean_str("Mail").str.to_lowercase(),
        phone=clean_phone("Phone Number"),
        company=clean_str("Employer"),
        created_on=clean_str("Created Date").str.to_datetime("%Y-%m-%dT%H:%M:%S", strict=False).dt.date(),
        lifetime_value=clean_number("Revenue"),
    )
